using UnityEngine;
using UnityEngine.Events;
using UnityEngine.InputSystem;
using UnityEngine.SceneManagement;

/// <summary>
/// Connects pause input and UI button callbacks to the pause service.
/// The pause overlay itself is generated by a Unity Editor installer.
/// </summary>
public sealed class PauseBootstrap : MonoBehaviour
{
    [Header("Scene Navigation")]
    [SerializeField] private string mainMenuSceneName = "MainMenu";

    [Header("UI Integration")]
    [SerializeField] private UnityEvent<bool> pauseStateChanged = new UnityEvent<bool>();

    [Header("Gameplay Dependencies")]
    [SerializeField] private Rigidbody2D ballRigidbody;

    private PauseService _pauseService;

    public bool IsPaused => _pauseService != null && _pauseService.IsPaused;

    /// <summary>State event used by the pause-only overlay to show and hide itself.</summary>
    public UnityEvent<bool> PauseStateChanged => pauseStateChanged;

    private void Awake()
    {
        _pauseService = new PauseService();
        _pauseService.StateChanged += HandlePauseStateChanged;
    }

    private void Update()
    {
        if (Keyboard.current != null && Keyboard.current.escapeKey.wasPressedThisFrame)
            TogglePause();
    }

    /// <summary>Connected to the pause menu's Continue button.</summary>
    public void ContinueGame()
    {
        _pauseService?.Resume();
    }

    /// <summary>
    /// Moves the ball to the arena center without resuming the game.
    /// Its current linear velocity is retained so it continues in the same direction
    /// and at the same speed when the pause is released.
    /// </summary>
    public void ResetBallToCenter()
    {
        if (!IsPaused)
        {
            Debug.LogWarning("The ball can only be reset while the game is paused.", this);
            return;
        }

        if (ballRigidbody == null)
        {
            Debug.LogError(
                "PauseBootstrap is missing Ball Rigidbody. Run Tools > PingPong > Install Pause System In Open Scene.",
                this);
            return;
        }

        Vector2 preservedVelocity = ballRigidbody.linearVelocity;

        // Rigidbody2D.position teleports the body without advancing the physics simulation.
        ballRigidbody.position = Vector2.zero;
        ballRigidbody.linearVelocity = preservedVelocity;
        ballRigidbody.angularVelocity = 0f;
    }

    /// <summary>Placeholder for the Settings button. No settings screen is created.</summary>
    public void OpenSettings()
    {
        Debug.LogWarning("Pause settings are not implemented yet.", this);
    }

    /// <summary>Connected to the pause menu's Return to Menu button.</summary>
    public void ReturnToMenu()
    {
        if (string.IsNullOrWhiteSpace(mainMenuSceneName))
        {
            Debug.LogError("Main Menu Scene Name is empty. Set it in the PauseBootstrap Inspector.", this);
            return;
        }

        if (!Application.CanStreamedLevelBeLoaded(mainMenuSceneName))
        {
            Debug.LogError(
                "Cannot load scene '" + mainMenuSceneName +
                "'. Check the scene name and add the scene to Build Profiles / Build Settings.",
                this);
            return;
        }

        // Never carry a paused time scale into another scene.
        _pauseService?.Resume();
        SceneManager.LoadScene(mainMenuSceneName);
    }

    /// <summary>Can be connected to another pause button or called by game code.</summary>
    public void TogglePause()
    {
        _pauseService?.TogglePause();
    }

    private void HandlePauseStateChanged(bool paused)
    {
        pauseStateChanged?.Invoke(paused);
    }

    private void OnDestroy()
    {
        if (_pauseService == null)
            return;

        _pauseService.StateChanged -= HandlePauseStateChanged;
        _pauseService.Resume();
    }
}
